INSERT INTO public.domains (id, slug, name, description, icon, color_hex) VALUES
  ('math', 'advanced-mathematics', 'Toán Cao Cấp & Đại Số', 'Giải tích nhiều biến, Đại số tuyến tính, Tối ưu hóa vi phân', 'Sigma', '#3b82f6'),
  ('discrete', 'discrete-mathematics', 'Toán Rời Rạc & Đồ Thị', 'Lý thuyết đồ thị, Logic mệnh đề, Cây bao trùm', 'Network', '#10b981'),
  ('cv', 'computer-vision', 'Thị Giác Máy Tính', 'Mạng tích chập CNN, Phát hiện biên cạnh, YOLO, Vision Transformers', 'Eye', '#8b5cf6'),
  ('cs', 'computer-science-systems', 'Khoa Học Máy Tính & Hệ Thống', 'Quản lý bộ nhớ con trỏ, Docker, Deadlock, B-Tree, Định lý CAP', 'Cpu', '#f59e0b')
INSERT INTO public.topics (id, domain_id, slug, title, description, difficulty, estimated_duration_minutes) VALUES
  ('math-gradient-descent', 'math', 'gradient-descent', 'Thuật Toán Hạ Độ Dốc (Gradient Descent)', 'Gradient Descent là thuật toán tối ưu hóa bậc một lặp lại nhằm tìm cực tiểu địa phương của hàm khả vi f(θ). Tại mỗi bước, vector tham số được cập nhật ngược hướng của vector gradient: θ_{t+1} = θ_t - η ∇f(θ_t), trong đó ∇f(θ) = [∂f/∂θ_1, ..., ∂f/∂θ_n]^T là vector các đạo hàm riêng chỉ hướng dốc nhất, và η > 0 là hệ số học (learning rate).', 'Intermediate', 45),
  ('math-linear-transformations', 'math', 'linear-transformations', 'Ma Trận Biến Đổi Tuyến Tính', 'Phép biến đổi tuyến tính T: V -> W giữa hai không gian vector là ánh xạ thỏa mãn hai tiên đề: 1) Tính cộng: T(u + v) = T(u) + T(v); 2) Tính thuần nhất: T(c * u) = c * T(u). Trong hệ tọa độ hữu hạn chiều, mọi biến đổi tuyến tính đều được biểu diễn hoàn toàn bằng phép nhân ma trận y = A * x, trong đó các cột của ma trận A chính là tọa độ ảnh của các vector cơ sở (basis vectors) sau biến đổi.', 'Intermediate', 45),
  ('math-eigenvalues-eigenvectors', 'math', 'eigenvalues-eigenvectors', 'Vector Riêng và Trị Riêng (Eigenvalues & Eigenvectors)', 'Cho ma trận vuông A kích thước n x n. Vector v khác vector không được gọi là vector riêng (eigenvector) và số thực/phức λ được gọi là trị riêng (eigenvalue) tương ứng nếu thỏa mãn phương trình: A * v = λ * v. Về mặt hình học, khi ma trận A biến đổi toàn bộ không gian, hướng của vector v hoàn toàn không bị xoay lệch, mà chỉ bị kéo dãn hoặc nén lại theo hệ số tỉ lệ bằng đúng λ. Phương trình đặc trưng: det(A - λI) = 0.', 'Advanced', 45),
  ('math-svd', 'math', 'svd', 'Phép Phân Tích Giá Trị Kỳ Dị (SVD)', 'Phân tích giá trị kỳ dị (SVD) là phép phân tích tổng quát cho mọi ma trận thực A kích thước m x n thành tích ba ma trận: A = U * Σ * V^T, trong đó U (m x m) và V (n x n) là các ma trận trực giao (orthogonal), và Σ (m x n) là ma trận đường chéo chứa các giá trị kỳ dị σ_1 ≥ σ_2 ≥ ... ≥ σ_r ≥ 0. Về mặt hình học, SVD phân rã mọi phép biến đổi tuyến tính thành 3 bước: Xoay hệ trục (V^T) -> Co dãn theo trục chính (Σ) -> Xoay tiếp (U).', 'Advanced', 45),
  ('math-hessian-saddle-points', 'math', 'hessian-matrix-saddle-points', 'Ma Trận Hessian và Điểm Yên Ngựa', 'Ma trận Hessian H của hàm số khả vi bậc hai f: R^n -> R là ma trận vuông n x n chứa các đạo hàm riêng cấp hai: H_{ij} = ∂^2 f / (∂x_i ∂x_j). Theo định lý Schwarz, nếu các đạo hàm riêng liên tục thì H là ma trận đối xứng. Dấu của các trị riêng của ma trận Hessian xác định độ cong của bề mặt: H xác định dương (tất cả λ > 0) -> Cực tiểu địa phương; H xác định âm -> Cực đại địa phương; H không xác định dấu (có cả λ > 0 và λ < 0) -> Điểm yên ngựa (Saddle Point).', 'Advanced', 45),
  ('math-taylor-series', 'math', 'taylor-series', 'Chuỗi Taylor và Xấp Xỉ Đa Thức', 'Chuỗi Taylor của một hàm số f(x) khả vi vô hạn tại lân cận điểm a là chuỗi lũy thừa: f(x) = ∑_{n=0}^∞ [f^{(n)}(a) / n!] * (x - a)^n = f(a) + f''(a)(x-a) + [f''''(a)/2!](x-a)^2 + ... Định lý Taylor cho phép xấp xỉ một hàm phi tuyến phức tạp bất kỳ quanh một điểm bằng một đa thức đơn giản, với phần dư sai số được ước lượng qua công thức Lagrange.', 'Intermediate', 45),
  ('math-fourier-transform', 'math', 'fourier-transform', 'Biến Đổi Fourier (Fourier Transform)', 'Biến đổi Fourier là phép toán tích phân biến đổi tín hiệu f(t) từ miền thời gian (time domain) sang miền tần số (frequency domain): F(ω) = ∫_{-∞}^∞ f(t) * e^{-i ω t} dt. Phép toán này chứng minh rằng mọi dạng sóng liên tục phức tạp đều có thể được phân tích thành tổng tích phân của các hàm sóng hình sin và cosin cơ bản với tần số, biên độ và pha xác định.', 'Advanced', 45),
  ('math-gauss-jordan-elimination', 'math', 'gauss-jordan-elimination', 'Phép Khử Gauss-Jordan và Nghịch Đảo Ma Trận', 'Phép khử Gauss-Jordan là thuật toán đại số tuyến tính dùng để giải hệ phương trình tuyến tính A * x = b, tìm hạng ma trận (rank) và tính ma trận nghịch đảo A^{-1}. Thuật toán sử dụng 3 phép biến đổi sơ cấp trên hàng: 1) Hoán vị hai hàng; 2) Nhân một hàng với hằng số khác 0; 3) Cộng bội số của một hàng vào hàng khác, để đưa ma trận bổ sung [A | b] về ma trận bậc thang rút gọn (Reduced Row Echelon Form - RREF).', 'Beginner', 45),
  ('math-gram-schmidt', 'math', 'gram-schmidt-orthogonalization', 'Trực Giao Hóa Gram-Schmidt', 'Quá trình Gram-Schmidt là phương pháp xây dựng một hệ trực chuẩn (orthonormal basis) {q_1, q_2, ..., q_k} từ một hệ vector độc lập tuyến tính {v_1, v_2, ..., v_k} trong không gian tích trong. Thuật toán hoạt động bằng cách: Chọn vector đầu tiên làm chuẩn; với mỗi vector tiếp theo, trừ đi hình chiếu vuông góc (projection) của nó lên các vector trước để thu được phần vuông góc hoàn toàn, sau đó chia cho độ dài (norm) để chuẩn hóa về độ dài bằng 1. Đây là nền tảng của phân tích QR (A = QR).', 'Intermediate', 45),
  ('math-double-integrals-green', 'math', 'double-integrals-green-theorem', 'Tích Phân Bội và Định Lý Green', 'Định lý Green thiết lập mối quan hệ cơ bản giữa tích phân đường (line integral) dọc theo đường cong kín C với tích phân kép (double integral) trên miền phẳng D được bao quanh bởi C: ∮_C (L dx + M dy) = ∬_D (∂M/∂x - ∂L/∂y) dA. Về mặt vật lý, định lý chứng minh rằng tổng độ xoáy vi mô (microscopic circulation/curl) của một trường vector bên trong miền chính bằng lưu số vĩ mô của trường đó chạy dọc theo đường biên ngoài cùng.', 'Advanced', 45),
  ('discrete-dijkstra-algorithm', 'discrete', 'dijkstra-algorithm', 'Lý Thuyết Đồ Thị & Thuật Toán Dijkstra', 'Thuật toán Dijkstra là thuật toán tham lam (greedy algorithm) giải bài toán tìm đường đi ngắn nhất từ một đỉnh nguồn đơn (Single-source shortest path) đến tất cả các đỉnh khác trong đồ thị có hướng hoặc vô hướng với trọng số các cạnh không âm (w(u, v) ≥ 0). Thuật toán duy trì mảng khoảng cách d[v] và tập hợp các đỉnh đã cố định khoảng cách ngắn nhất. Sử dụng hàng đợi ưu tiên (Min-Heap), độ phức tạp thời gian đạt O((V + E) log V).', 'Intermediate', 45),
  ('discrete-minimum-spanning-tree', 'discrete', 'minimum-spanning-tree-kruskal-prim', 'Cây Bao Trùm Tối Thiểu (Kruskal & Prim)', 'Cho đồ thị vô hướng liên thông có trọng số G = (V, E). Cây bao trùm tối thiểu (MST) là một đồ thị con T = (V, E_T) chứa toàn bộ |V| đỉnh của G, không chứa chu trình (cycle), có đúng |V| - 1 cạnh và tổng trọng số các cạnh là nhỏ nhất. Thuật toán Kruskal sắp xếp tất cả các cạnh theo thứ tự tăng dần và thêm dần vào cây bằng cấu trúc Disjoint Set Union (DSU) để kiểm tra chu trình; Thuật toán Prim bắt đầu từ 1 đỉnh và mở rộng dần vết cắt (cut property) bằng Min-Heap.', 'Intermediate', 45),
  ('discrete-propositional-logic-boolean', 'discrete', 'propositional-logic-boolean-algebra', 'Logic Mệnh Đề và Đại Số Boole', 'Logic mệnh đề là hệ thống hình thức khảo sát các mệnh đề mang giá trị chân lý nhị phân {Đúng, Sai} (hoặc {1, 0}). Các phép toán cơ bản gồm: Phủ định (NOT ¬), Tuyển (OR ∨), Hội (AND ∧), Kéo theo (IMPLIES →), và Tương đương (IFF ↔). Đại số Boole cung cấp hệ tiên đề đại số (giao hoán, kết hợp, phân phối, De Morgan: ¬(p ∧ q) ≡ ¬p ∨ ¬q) đóng vai trò là nền tảng toán học trực tiếp cho thiết kế cổng logic phần cứng máy tính và câu lệnh điều kiện trong lập trình.', 'Beginner', 45),
  ('discrete-mathematical-induction-recurrence', 'discrete', 'mathematical-induction-recurrence', 'Quy Nạp Toán Học và Hệ Thức Truy Hồi', 'Quy nạp toán học là phương pháp chứng minh mệnh đề P(n) đúng với mọi số tự nhiên n ≥ n_0. Quy trình gồm 2 bước: 1) Cơ sở quy nạp: Chứng minh P(n_0) đúng; 2) Bước quy nạp: Giả sử P(k) đúng (giả thiết quy nạp), chứng minh P(k+1) cũng đúng. Hệ thức truy hồi định nghĩa dãy số {a_n} thông qua một hoặc nhiều số hạng đứng trước (ví dụ dãy Fibonacci a_n = a_{n-1} + a_{n-2}). Định lý Thợ (Master Theorem) cung cấp công thức nghiệm giải độ phức tạp thuật toán chia để trị T(n) = a T(n/b) + f(n).', 'Intermediate', 45),
  ('discrete-equivalence-relations-partitions', 'discrete', 'equivalence-relations-partitions', 'Quan Hệ Tương Đương và Phân Hoạch Tập Hợp', 'Quan hệ hai ngôi R trên tập hợp A được gọi là quan hệ tương đương nếu thỏa mãn đồng thời 3 tính chất: 1) Phản xạ: a R a với mọi a ∈ A; 2) Đối xứng: Nếu a R b thì b R a; 3) Bắc cầu: Nếu a R b và b R c thì a R c. Định lý cơ bản về quan hệ tương đương khẳng định: Mọi quan hệ tương đương trên A đều tạo ra một phân hoạch (partition) duy nhất chia tập A thành các lớp tương đương rời nhau không rỗng, và ngược lại. Điển hình là quan hệ đồng dư modulo n: a ≡ b (mod n).', 'Intermediate', 45),
  ('discrete-pigeonhole-principle', 'discrete', 'pigeonhole-principle', 'Nguyên Lý Dirichlet (Nguyên Lý Chuồng Bồ Câu)', 'Nguyên lý Dirichlet phát biểu: Nếu k + 1 hoặc nhiều hơn đồ vật được đặt vào k hộp, thì chắc chắn có ít nhất một hộp chứa từ hai đồ vật trở lên. Dạng tổng quát: Nếu N đồ vật được đặt vào k hộp, thì tồn tại ít nhất một hộp chứa ⌈N / k⌉ đồ vật. Mặc dù có phát biểu cực kỳ đơn giản, nguyên lý này là công cụ toán học tối thượng để chứng minh sự tồn tại của các cấu trúc trùng lặp, chu kỳ, hoặc sự xung đột băm mà không cần phải chỉ rõ phần tử cụ thể.', 'Beginner', 45),
  ('discrete-euler-hamilton-cycles', 'discrete', 'euler-hamilton-cycles', 'Chu Trình Euler và Chu Trình Hamilton', 'Đường đi Euler là đường đi trong đồ thị đi qua mỗi CẠNH đúng một lần. Đồ thị liên thông có chu trình Euler khi và chỉ khi mọi đỉnh đều có bậc chẵn (Định lý Euler giải bài toán 7 cây cầu Königsberg năm 1736, khai sinh lý thuyết đồ thị). Ngược lại, Chu trình Hamilton là chu trình đi qua mỗi ĐỈNH đúng một lần. Trong khi kiểm tra đồ thị Euler giải được trong thời gian tuyến tính O(V + E), bài toán kiểm tra chu trình Hamilton và bài toán Người du lịch (TSP) là bài toán NP-đầy đủ (NP-Complete), chưa có thuật toán đa thức nào giải được.', 'Intermediate', 45),
  ('discrete-bfs-dfs-graph-traversal', 'discrete', 'bfs-dfs-graph-traversal', 'Duyệt Đồ Thị: BFS và DFS', 'BFS (Tìm kiếm theo chiều rộng) và DFS (Tìm kiếm theo chiều sâu) là hai chiến lược nền tảng để duyệt qua mọi đỉnh của đồ thị: BFS sử dụng cấu trúc hàng đợi (Queue - FIFO) để thăm các đỉnh theo từng lớp khoảng cách tăng dần từ gốc, đảm bảo tìm ra đường đi ngắn nhất trên đồ thị không trọng số; DFS sử dụng ngăn xếp (Stack - LIFO hoặc đệ quy) để đi sâu nhất có thể theo một nhánh trước khi quay lui (Backtracking). Cả hai thuật toán đều có độ phức tạp thời gian O(V + E).', 'Beginner', 45),
  ('discrete-graph-coloring-four-color', 'discrete', 'graph-coloring-four-color-theorem', 'Tô Màu Đồ Thị và Định Lý Bốn Màu', 'Tô màu đồ thị (Graph Coloring) là việc gán các nhãn màu cho các đỉnh sao cho không có hai đỉnh kề nhau có cùng màu. Sắc số χ(G) là số lượng màu tối thiểu cần thiết để tô đồ thị G. Định lý Bốn Màu (Appel & Haken 1976) chứng minh rằng mọi đồ thị phẳng (planar graph - bản đồ không có đường biên cắt nhau) đều có thể tô được bằng không quá 4 màu. Đây là định lý lớn đầu tiên trong lịch sử toán học được chứng minh bằng máy tính thông qua việc kiểm tra vét cạn 1.936 cấu hình đồ thị.', 'Intermediate', 45),
  ('discrete-combinatorics-binomial', 'discrete', 'combinatorics-binomial-theorem', 'Tổ Hợp, Chỉnh Hợp và Nhị Thức Newton', 'Tổ hợp C(n, k) = n! / (k!(n-k)!) là số cách chọn k phần tử từ tập n phần tử mà không quan tâm đến thứ tự. Chỉnh hợp P(n, k) = n! / (n-k)! tính số cách chọn có phân biệt thứ tự. Định lý Nhị thức Newton khai triển lũy thừa của một nhị thức: (x + y)^n = ∑_{k=0}^n C(n, k) x^{n-k} y^k. Các hệ số nhị thức tạo thành tam giác Pascal đối xứng với hệ thức Pascal: C(n, k) = C(n-1, k-1) + C(n-1, k).', 'Beginner', 45),
  ('cv-convolution-cnn', 'cv', 'convolutional-neural-networks', 'Phép Tích Chập 2D & Mạng Nơ-ron CNN', 'Phép tích chập 2D trên ảnh số là phép toán trượt một ma trận trọng số nhỏ (Kernel/Filter kích thước k x k) qua toàn bộ ma trận điểm ảnh đầu vào I, thực hiện nhân từng phần tử tương ứng rồi cộng lại: (I * K)(x, y) = ∑_i ∑_j I(x - i, y - j) K(i, j). Trong mạng CNN, các giá trị kernel không được định nghĩa thủ công mà được tự động học qua Backpropagation. Đặc tính then chốt của CNN là chia sẻ trọng số (Weight Sharing) và tính bất biến tịnh tiến (Translation Equivariance).', 'Intermediate', 45),
  ('cv-edge-detection-canny-sobel', 'cv', 'edge-detection-canny-sobel', 'Phát Hiện Biên Cạnh: Toán Tử Sobel & Thuật Toán Canny', 'Biên cạnh (Edge) là những vị trí trong ảnh có sự thay đổi đột ngột về cường độ sáng. Toán tử Sobel tính xấp xỉ đạo hàm bậc nhất của ảnh bằng hai kernel 3x3 (G_x phát hiện cạnh dọc, G_y phát hiện cạnh ngang): Độ lớn gradient G = √(G_x^2 + G_y^2), hướng gradient θ = arctan(G_y / G_x). Thuật toán Canny (1986) hoàn thiện quy trình phát hiện biên cạnh tối ưu qua 5 bước: 1) Làm mịn ảnh bằng Gaussian Filter; 2) Tính Gradient Sobel; 3) Triệt tiêu không cực đại (Non-Maximum Suppression - NMS) để làm mỏng biên về 1 pixel; 4) Phân ngưỡng kép (Double Thresholding); 5) Nối biên bằng phân tích liên thông (Hysteresis Tracking).', 'Intermediate', 45),
  ('cv-color-spaces-morphology', 'cv', 'color-spaces-morphology', 'Không Gian Màu & Biến Đổi Hình Thái Học', 'Không gian màu là mô hình toán học biểu diễn màu sắc dưới dạng bộ tọa độ số: RGB phù hợp cho màn hình phát sáng nhưng các kênh bị phụ thuộc mạnh vào cường độ chiếu sáng; HSV (Hue - Sắc thái, Saturation - Độ bão hòa, Value - Độ sáng) tách biệt hoàn toàn thông tin màu sắc khỏi ánh sáng môi trường, rất lý tưởng cho việc lọc màu theo ngưỡng (Color Thresholding). Biến đổi hình thái học (Morphology) trên ảnh nhị phân gồm hai phép toán nền tảng dựa trên phần tử cấu trúc (Structuring Element): 1) Giãn nở (Dilation - phóng to vùng trắng, lấp lỗ hổng); 2) Xói mòn (Erosion - bào mòn đường viền, xóa nhiễu li ti); kết hợp thành Opening (Erosion rồi Dilation) và Closing.', 'Beginner', 45),
  ('cv-yolo-object-detection', 'cv', 'yolo-real-time-object-detection', 'Nhận Diện Vật Thể Thời Gian Thực YOLO', 'YOLO (Redmon et al., 2016) tái định nghĩa bài toán nhận diện vật thể từ phân loại nhiều giai đoạn (Two-stage như R-CNN) thành bài toán hồi quy đơn nhất (Single-stage regression) từ toàn bộ điểm ảnh đầu vào sang tọa độ Bounding Box và xác suất lớp đối tượng. Mô hình chia bức ảnh thành lưới S x S ô. Mỗi ô chịu trách nhiệm dự đoán B hộp bao quanh (x, y, w, h), độ tin cậy Confidence = Pr(Object) * IoU, và phân phối xác suất lớp C. Thuật toán chạy qua toàn bộ ảnh đúng 1 lần (You Only Look Once), đạt tốc độ xử lý thời gian thực từ 45 đến 150+ FPS trên GPU.', 'Advanced', 45),
  ('cv-sift-harris-corner', 'cv', 'sift-harris-corner-features', 'Trích Xuất Đặc Trưng SIFT và Điểm Góc Harris', 'Điểm góc (Corner) là điểm ảnh mà khi di chuyển một cửa sổ quan sát nhỏ theo bất kỳ hướng nào thì cường độ sáng cũng thay đổi rõ rệt. Toán tử Harris Corner (1988) sử dụng ma trận tự tương quan M (Structure Tensor) dựa trên gradient ảnh để tìm các điểm có cả hai trị riêng của M đều lớn. Thuật toán SIFT (Lowe, 1999) nâng cấp đặc trưng đạt tính bất biến với cả tỷ lệ phóng to/thu nhỏ (Scale Invariance) và góc xoay (Rotation Invariance) thông qua không gian tỷ lệ Difference of Gaussians (DoG), gán hướng chủ đạo và tạo vector mô tả đặc trưng 128 chiều.', 'Advanced', 45),
  ('cv-hough-transform', 'cv', 'hough-transform', 'Phép Biến Đổi Hough (Hough Transform)', 'Phép biến đổi Hough là kỹ thuật trích xuất đặc trưng dùng để phát hiện các hình dạng hình học biểu diễn được dưới dạng tham số (đường thẳng, đường tròn, elip) ngay cả khi hình ảnh bị đứt đoạn hoặc có nhiều nhiễu hạt. Thay vì dùng phương trình y = mx + c (gặp lỗi vô cực khi đường thẳng thẳng đứng), đường thẳng được biểu diễn trong không gian tham số cực Hesse: ρ = x cos θ + y sin θ. Mỗi điểm ảnh biên cạnh trong không gian ảnh (x, y) sẽ tạo thành một đường cong hình sin trong không gian Hough (ρ, θ). Giao điểm của nhiều đường cong hình sin tích lũy số phiếu bầu (accumulator array) cao nhất chính là đường thẳng đi qua các điểm đó.', 'Intermediate', 45),
  ('cv-resnet-skip-connections', 'cv', 'resnet-deep-residual-learning', 'Kiến Trúc ResNet & Đường Nối Tắt Skip Connection', 'Khi mạng nơ-ron tích chập ngày càng sâu (hàng chục đến hàng trăm tầng), việc huấn luyện bị suy thoái (Degradation Problem) do triệt tiêu gradient (Vanishing Gradient). ResNet (He et al., Microsoft Research 2015) giải quyết triệt để vấn đề này bằng khối phần dư (Residual Block) tích hợp kết nối tắt (Skip / Shortcut Connection): y = F(x, {W_i}) + x. Thay vì ép các lớp nơ-ron học trực tiếp ánh xạ mục tiêu H(x), mạng chỉ cần học phần dư sai số F(x) = H(x) - x. Nếu việc học thêm tầng là dư thừa, mạng chỉ cần đặt F(x) = 0 để bảo toàn ánh xạ đồng nhất (Identity Mapping).', 'Advanced', 45),
  ('cv-unet-semantic-segmentation', 'cv', 'unet-semantic-segmentation', 'Phân Vùng Ảnh U-Net & Kiến Trúc Encoder-Decoder', 'Phân vùng ảnh ngữ nghĩa (Semantic Segmentation) là bài toán gán nhãn phân loại cho từng điểm ảnh đơn lẻ (Pixel-level classification). U-Net (Ronneberger et al., 2015) sở hữu kiến trúc hình chữ U đối xứng gồm hai nhánh: 1) Nhánh co (Encoder / Contracting path): Sử dụng các lớp tích chập và pooling liên tiếp để bắt ngữ cảnh trừu tượng (Context); 2) Nhánh giãn (Decoder / Expansive path): Sử dụng chuyển vị tích chập (Transposed Convolution / Upsampling) để khôi phục độ phân giải không gian. Điểm đột phá là các đường nối tắt (Skip Connections) sao chép trực tiếp bản đồ đặc trưng độ phân giải cao từ Encoder sang Decoder để giữ trọn vẹn chi tiết mép viền.', 'Advanced', 45),
  ('cv-optical-flow-lucas-kanade', 'cv', 'optical-flow-lucas-kanade', 'Dòng Quang Học Lucas-Kanade (Optical Flow)', 'Dòng quang học (Optical Flow) là hình ảnh biểu diễn chuyển động biểu kiến của các điểm ảnh giữa hai khung hình liên tiếp trong video do sự chuyển dịch của vật thể hoặc camera. Giả định bảo toàn độ sáng (Brightness Constancy): I(x, y, t) = I(x + dx, y + dy, t + dt). Khai triển Taylor dẫn tới phương trình cơ bản: I_x * u + I_y * v + I_t = 0 (1 phương trình với 2 ẩn u = dx/dt, v = dy/dt - Vấn đề Aperture). Thuật toán Lucas-Kanade (1981) giải quyết bằng giả định các điểm lân cận trong cửa sổ nhỏ có cùng vận tốc chuyển động, tạo hệ phương trình giải bằng phương pháp bình phương tối thiểu Least Squares.', 'Advanced', 45),
  ('cv-vision-transformers-vit', 'cv', 'vision-transformers-vit', 'Vision Transformer (ViT) & Cơ Chế Tự Chú Ý', 'Vision Transformer (Dosovitskiy et al., Google Research 2020) chứng minh rằng kiến trúc Transformer chuẩn trong xử lý ngôn ngữ tự nhiên (NLP) hoàn toàn có thể áp dụng trực tiếp lên hình ảnh mà không cần các lớp tích chập CNN truyền thống. Thuật toán cắt bức ảnh thành lưới các mảnh nhỏ cố định (Patches kích thước 16x16 pixel), trải phẳng thành các vector 1D, chiếu tuyến tính thành chuỗi Patch Embeddings, cộng thêm Positional Embeddings và đưa vào khối Transformer Encoder chuẩn. Cơ chế Multi-Head Self-Attention tính toán mối tương quan giữa mọi cặp mảnh ảnh ngay từ tầng đầu tiên, cho phép bắt ngữ cảnh toàn cục (Global Context).', 'Advanced', 45),
  ('cs-pointers-memory-management', 'cs', 'pointers-memory-management', 'Quản Lý Bộ Nhớ C/C++ & Con Trỏ (Pointers)', 'Con trỏ (Pointer) trong C/C++ là một biến lưu trữ địa chỉ ô nhớ trong bộ nhớ RAM nơi biến khác đang cư ngụ. Toán tử & lấy địa chỉ ô nhớ, toán tử * (Dereference) truy xuất nội dung tại địa chỉ mà con trỏ chỉ tới. Không gian bộ nhớ của tiến trình được chia thành các phân vùng chính: Phân vùng mã lệnh (Text/Code), Dữ liệu toàn cục (Data/BSS), Ngăn xếp (Stack - cấp phát tự động, cấu trúc LIFO nhanh chóng cho biến cục bộ), và Vùng nhớ động (Heap - cấp phát thủ công qua malloc/new, tự chịu trách nhiệm giải phóng qua free/delete). Lỗi quản lý bộ nhớ dẫn tới rò rỉ bộ nhớ (Memory Leak), con trỏ lơ lửng (Dangling Pointer) và lỗi truy cập trái phép (Segmentation Fault).', 'Intermediate', 45),
  ('cs-docker-containers-namespaces', 'cs', 'docker-containers-namespaces', 'Công Nghệ Đóng Gói Docker, Namespaces & Cgroups', 'Docker Container là công nghệ ảo hóa ở cấp độ hệ điều hành (OS-level Virtualization) cho phép đóng gói ứng dụng cùng toàn bộ thư viện phụ thuộc thành một đơn vị chuẩn hóa có thể chạy nhất quán trên mọi môi trường. Khác với máy ảo (Virtual Machine - VM) yêu cầu cả một hệ điều hành khách (Guest OS) cồng kềnh chạy trên Hypervisor, Container dùng chung Kernel của máy chủ chủ (Host Kernel) và được cách ly bằng hai tính năng cốt lõi của Linux Kernel: 1) Linux Namespaces (cách ly tầm nhìn: PID, Network, Mount, IPC, UTS, User); 2) Control Groups (cgroups - giới hạn và giám sát tài nguyên phần cứng: CPU, RAM, Disk I/O); kết hợp hệ thống tập tin nhiều lớp Union File System (Overlay2) cho phép tái sử dụng image layers cực nhẹ.', 'Intermediate', 45),
  ('cs-process-vs-thread-concurrency', 'cs', 'process-vs-thread-concurrency', 'Tiến Trình vs Luồng & Lập Trình Đồng Thời', 'Tiến trình (Process) là một chương trình đang trong trạng thái thực thi, sở hữu không gian địa chỉ bộ nhớ độc lập, bảng mô tả tệp tin riêng biệt và khối điều khiển tiến trình (PCB - Process Control Block). Luồng (Thread) là đơn vị nhỏ nhất được CPU lên lịch thực thi (LWP - Light-Weight Process) nằm bên trong tiến trình. Các luồng trong cùng tiến trình dùng chung mã lệnh, dữ liệu toàn cục và vùng nhớ Heap, nhưng mỗi luồng có ngăn xếp (Stack) và thanh ghi riêng. Chạy đồng thời nhiều luồng gây ra xung đột truy cập tài nguyên (Race Condition), đòi hỏi các cơ chế đồng bộ hóa: Mutex, Semaphore, Spinlock.', 'Intermediate', 45),
  ('cs-deadlock-coffman-conditions', 'cs', 'deadlock-coffman-conditions', 'Bế Tắc Hệ Thống (Deadlock) & 4 Điều Kiện Coffman', 'Bế tắc (Deadlock) là tình trạng một tập hợp các tiến trình bị phong tỏa vĩnh viễn vì mỗi tiến trình đều đang giữ một tài nguyên và chờ đợi tài nguyên khác đang bị một tiến trình khác trong tập hợp chiếm giữ. Edward G. Coffman (1971) đã chứng minh Deadlock xảy ra khi và chỉ khi 4 điều kiện sau đồng thời thỏa mãn: 1) Loại trừ tương hỗ (Mutual Exclusion): Tài nguyên không thể chia sẻ đồng thời; 2) Giữ và chờ (Hold and Wait): Tiến trình đang giữ ít nhất 1 tài nguyên và chờ cấp phát thêm; 3) Không thể tước đoạt (No Preemption): Tài nguyên chỉ được giải phóng tự nguyện bởi tiến trình nắm giữ; 4) Chờ đợi vòng tròn (Circular Wait): Tồn tại chu trình chuỗi P_0 -> P_1 -> ... -> P_n -> P_0. Thuật toán Banker của Dijkstra được dùng để phòng tránh Deadlock.', 'Intermediate', 45),
  ('cs-virtual-memory-paging', 'cs', 'virtual-memory-paging', 'Bộ Nhớ Ảo, Phân Trang & Bảng Trang (TLB)', 'Bộ nhớ ảo (Virtual Memory) là kỹ thuật quản lý bộ nhớ của hệ điều hành cung cấp cho mỗi tiến trình một ảo giác rằng nó đang sở hữu toàn bộ một không gian địa chỉ liên tục và khổng lồ, độc lập hoàn toàn với bộ nhớ vật lý thực tế. Kỹ thuật Phân trang (Paging) chia không gian địa chỉ ảo thành các Trang (Pages - thường là 4KB) và bộ nhớ RAM vật lý thành các Khung trang (Page Frames). Bộ quản lý bộ nhớ phần cứng (MMU) chuyển đổi địa chỉ ảo thành địa chỉ vật lý thông qua Bảng trang (Page Table). Bộ đệm chuyển đổi Translation Lookaside Buffer (TLB) đóng vai trò cache phần cứng cực nhanh cho các bản dịch gần nhất. Khi trang yêu cầu chưa có trong RAM, ngắt lỗi trang (Page Fault) được kích hoạt để nạp trang từ ổ đĩa (Swap).', 'Advanced', 45),
  ('cs-tcp-3way-handshake', 'cs', 'tcp-3way-handshake', 'Giao Thức Bắt Tay 3 Bước TCP (3-Way Handshake)', 'TCP (Transmission Control Protocol) là giao thức tầng truyền vận hướng kết nối, tin cậy, đảm bảo dữ liệu đến đúng thứ tự và không bị mất mát trên môi trường mạng Internet không tin cậy. Trước khi truyền dữ liệu, kết nối bắt buộc phải được thiết lập thông qua quy trình bắt tay 3 bước (Three-way Handshake): 1) Client gửi cờ SYN với số thứ tự khởi tạo ngẫu nhiên ISN(c); 2) Server phản hồi cờ SYN-ACK với ISN(s) của server và ACK = ISN(c) + 1; 3) Client gửi cờ ACK = ISN(s) + 1 xác nhận. Sau 3 bước này, cả hai bên đều đồng bộ hóa số thứ tự (Sequence Numbers) và sẵn sàng truyền luồng dữ liệu song công (Full-duplex).', 'Intermediate', 45),
  ('cs-cap-theorem-distributed-systems', 'cs', 'cap-theorem-distributed-systems', 'Định Lý CAP & Thiết Kế Hệ Thống Phân Tán', 'Định lý CAP (Eric Brewer, 2000; chứng minh hình thức bởi Gilbert & Lynch, 2002) phát biểu rằng một hệ thống dữ liệu phân tán chỉ có thể đảm bảo tối đa hai trong ba thuộc tính sau tại cùng một thời điểm: 1) Tính nhất quán (Consistency - Mọi thao tác đọc đều nhận được dữ liệu được ghi mới nhất hoặc báo lỗi); 2) Tính sẵn sàng (Availability - Mọi yêu cầu không bị lỗi đều nhận được phản hồi không có lỗi, dù có thể không phải dữ liệu mới nhất); 3) Khả năng chịu lỗi phân vùng mạng (Partition Tolerance - Hệ thống vẫn tiếp tục hoạt động dù mạng bị đứt cáp chia cắt các máy chủ). Vì phân vùng mạng (P) trong thế giới vật lý là không thể tránh khỏi, kiến trúc sư chỉ được quyền chọn lựa giữa CP (Ưu tiên nhất quán) hoặc AP (Ưu tiên sẵn sàng).', 'Advanced', 45),
  ('cs-btree-database-indexing', 'cs', 'btree-database-indexing', 'Chỉ Mục Cơ Sở Dữ Liệu B-Tree & B+Tree', 'B-Tree (Bayer & McCreight, 1972) là cấu trúc dữ liệu cây tìm kiếm tự cân bằng nhiều nhánh (Self-balancing m-way search tree) được thiết kế đặc biệt tối ưu cho hệ thống lưu trữ khối trên đĩa từ (HDD) và ổ cứng thể rắn (SSD). Khác với cây nhị phân (AVL, Red-Black) chỉ có 2 nhánh con khiến chiều cao cây rất lớn, B-Tree cho phép mỗi nút chứa hàng trăm khóa (Keys) và hàng trăm con trỏ nhánh con, giữ cho chiều cao cây cực kỳ thấp (thường chỉ từ 3 đến 4 tầng cho hàng triệu bản ghi). Biến thể B+Tree lưu toàn bộ dữ liệu thực tế tại các nút lá (Leaf nodes) và nối các lá bằng danh sách liên kết đôi (Doubly Linked List), cho phép thực hiện các truy vấn quét dải (Range Scan: SELECT * WHERE age BETWEEN 20 AND 30) với tốc độ tức thì.', 'Intermediate', 45),
  ('cs-message-queues-event-driven', 'cs', 'message-queues-event-driven-architecture', 'Hàng Đợi Thông Điệp & Kiến Trúc Hướng Sự Kiện', 'Kiến trúc hướng sự kiện (Event-Driven Architecture) là mô hình thiết kế phần mềm trong đó các dịch vụ giao tiếp với nhau bất đồng bộ thông qua việc phát sinh, phát hiện và tiêu thụ các Sự kiện (Events). Hàng đợi thông điệp (Message Queue như RabbitMQ, Apache Kafka, AWS SQS) đóng vai trò bộ đệm trung gian (Message Broker) thực hiện giải phóng liên kết (Decoupling) giữa bên sản xuất (Producer) và bên tiêu thụ (Consumer). Hệ thống cung cấp các mô hình phân phối: Điểm - Điểm (Point-to-Point) và Xuất bản - Đăng ký (Pub/Sub). Các cơ chế đảm bảo truyền tin: Tối đa một lần (At-most-once), Ít nhất một lần (At-least-once), và Đúng một lần (Exactly-once).', 'Intermediate', 45),
  ('cs-hash-tables-collision-resolution', 'cs', 'hash-tables-collision-resolution', 'Bảng Băm & Thuật Toán Giải Quyết Đụng Độ', 'Bảng băm (Hash Table) là cấu trúc dữ liệu mảng kết hợp (Associative Array) ánh xạ các Khóa (Keys) sang Giá trị (Values) với thời gian tìm kiếm, chèn và xóa trung bình đạt tốc độ lý tưởng O(1). Hàm băm h(k) chuyển đổi một khóa có độ dài bất kỳ (ví dụ chuỗi văn bản) thành một chỉ số số nguyên nằm trong phạm vi mảng [0, m-1]. Do nguyên lý chuồng bồ câu Dirichlet, đụng độ băm (Hash Collision: h(k_1) = h(k_2) với k_1 ≠ k_2) là điều chắc chắn xảy ra. Hai chiến lược giải quyết đụng độ chính: 1) Băm riêng biệt (Separate Chaining: mỗi ô mảng là một danh sách liên kết chứa các phần tử đụng độ); 2) Địa chỉ mở (Open Addressing: dò tuyến tính Linear Probing, dò bậc hai, hoặc băm kép để tìm ô trống tiếp theo trong mảng).', 'Beginner', 45)
