  ('notif-002', 'usr-learner-001', 'REPORT_READY', 'Báo cáo Feynman đã sẵn sàng', 'Bé Bắp đã hoàn tất nghe bài giảng "Cơ chế Docker Container". Điểm Clarity: 88/100.', '/stage/sample/report?topic=Cơ%20chế%20Docker%20Container&score=88', '{"score": 88}', FALSE),
