  difficulty = EXCLUDED.difficulty;

-- 3. Knowledge Graph Directional Edges Table
ON CONFLICT (source_topic_id, target_topic_id, relationship_type) DO NOTHING;

-- 4. Preconfigured Accounts for Two-Role Feynman Stage
ON CONFLICT (id) DO UPDATE SET
  username = EXCLUDED.username,
  full_name = EXCLUDED.full_name,
  role = EXCLUDED.role;

-- 5. Notifications Table (Bảng thứ 13)
CREATE TABLE IF NOT EXISTS public.notifications (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
    type TEXT NOT NULL CHECK (type IN ('SRS_REMINDER', 'SESSION_RESUME', 'REPORT_READY', 'STREAK_ALERT', 'SYSTEM')),
    title TEXT NOT NULL,
    message TEXT NOT NULL,
    action_url TEXT,
    metadata JSONB DEFAULT '{}'::jsonb,
    is_read BOOLEAN DEFAULT FALSE,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_notifications_user_unread 
ON public.notifications(user_id, is_read, created_at DESC);

-- Seed Initial Notifications for Demo
ON CONFLICT (id) DO NOTHING;

-- ============================================================================
-- 5. AI System Prompts Table (Bảng thứ 14: ai_system_prompts)
-- ============================================================================
CREATE TABLE IF NOT EXISTS public.ai_system_prompts (
    id TEXT PRIMARY KEY,
    prompt_key TEXT UNIQUE NOT NULL,
    title TEXT NOT NULL,
    category TEXT NOT NULL CHECK (category IN ('PERSONA', 'EVALUATOR', 'SOCRATIC', 'SYSTEM')),
    description TEXT,
    system_prompt TEXT NOT NULL,
    parameters JSONB NOT NULL DEFAULT '{
        "model": "gemini-1.5-flash",
        "temperature": 0.7,
        "max_tokens": 1024,
        "top_p": 0.95,
        "skepticism_level": 5
    }'::jsonb,
    is_active BOOLEAN DEFAULT TRUE,
    version INT DEFAULT 1,
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_ai_prompts_key ON public.ai_system_prompts(prompt_key);

-- Seed System Prompts
ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  category = EXCLUDED.category,
  description = EXCLUDED.description,
  system_prompt = EXCLUDED.system_prompt,
  parameters = EXCLUDED.parameters,
  updated_at = NOW();

-- Verification Query
SELECT d.name as domain, COUNT(t.id) as topic_count
FROM public.domains d
LEFT JOIN public.topics t ON d.id = t.domain_id
GROUP BY d.id, d.name;
